import heapq
from typing import List, Mapping, Optional, Tuple


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits:
        raise KeyError(src)
    if dst not in limits:
        raise KeyError(dst)
    if src == dst:
        raise ValueError("src and dst must be different")

    pq = [(-10**18, 0, [src])]
    best = {}

    while pq:
        neg_load, hops, path = heapq.heappop(pq)
        load = -neg_load
        if load > 10**17:
            load = 10**18
        current = path[-1]

        if current in best:
            prev_load, prev_hops, prev_path = best[current]
            if load < prev_load or (load == prev_load and hops > prev_hops) or (load == prev_load and hops == prev_hops and path >= prev_path):
                continue

        best[current] = (load, hops, path)

        if current == dst:
            return (load, path) if load <= 10**17 else None

        for neighbor, limit in sorted(limits.get(current, {}).items()):
            new_load = min(load, limit)
            new_path = path + [neighbor]
            heapq.heappush(pq, (-new_load, hops + 1, new_path))

    return None
