def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits:
        raise KeyError(src)
    if dst not in limits:
        raise KeyError(dst)
    if src == dst:
        raise ValueError("src and dst must be different")

    # Priority queue: (-load, hops, path)
    # Use negative load for max-heap behavior
    pq = [(-float('inf'), 0, [src])]
    best = {}

    while pq:
        neg_load, hops, path = heapq.heappop(pq)
        load = -neg_load if neg_load != float('-inf') else float('inf')
        current = path[-1]

        # Check if we have a better path to this node already
        if current in best:
            prev_load, prev_hops, prev_path = best[current]
            if load < prev_load:
                continue
            if load == prev_load and hops > prev_hops:
                continue
            if load == prev_load and hops == prev_hops and path >= prev_path:
                continue

        best[current] = (load, hops, path)

        if current == dst:
            return (int(load), path) if load != float('inf') else None

        for neighbor in sorted(limits.get(current, {}).keys()):
            limit = limits[current][neighbor]
            new_load = min(load, limit)
            new_path = path + [neighbor]
            heapq.heappush(pq, (-new_load, hops + 1, new_path))

    return None
